<?php require 'config/db.php';require 'includes/functions.php';$id=(int)($_GET['id']??0);
if($_SERVER['REQUEST_METHOD']==='POST'){require_login();verify_csrf();$act=$_POST['action']??'';
 if($act==='expand' && is_role('admin','hospital','requester')){$st=$conn->prepare("UPDATE blood_requests SET broadcast_radius=LEAST(25,broadcast_radius+5),status='matching' WHERE id=?");$st->bind_param('i',$id);$st->execute();create_matches($conn,$id);case_event($conn,$id,'Broadcast expanded','Search radius expanded by 5 km');audit($conn,'Expanded emergency radius','blood_request',$id,'+5 km');flash('success','Broadcast radius expanded and matching refreshed.');}
 if($act==='accept' && is_role('donor')){$uid=(int)user()['id'];$st=$conn->prepare("UPDATE request_matches SET match_status='accepted',responded_at=NOW() WHERE request_id=? AND donor_id=? AND match_status IN ('notified','suggested')");$st->bind_param('ii',$id,$uid);$st->execute();if($st->affected_rows){$up=$conn->prepare("UPDATE blood_requests SET status='accepted' WHERE id=?");$up->bind_param('i',$id);$up->execute();case_event($conn,$id,'Donor accepted','A matched donor accepted the emergency request');audit($conn,'Accepted emergency request','blood_request',$id,'Donor response');flash('success','You accepted this emergency request.');}}
 if($act==='next' && is_role('admin','hospital')){$st=$conn->prepare('SELECT status,hospital_id,units FROM blood_requests WHERE id=?');$st->bind_param('i',$id);$st->execute();$r=$st->get_result()->fetch_assoc();$order=['verified'=>'matching','matching'=>'accepted','accepted'=>'arrived','arrived'=>'collected','collected'=>'completed'];$next=$r?$order[$r['status']]??null:null;if($next){$up=$conn->prepare('UPDATE blood_requests SET status=? WHERE id=?');$up->bind_param('si',$next,$id);$up->execute();case_event($conn,$id,'Status: '.status_label($next),'Case advanced by '.user()['role']);audit($conn,'Advanced case status','blood_request',$id,$next);if($next==='completed'){$m=$conn->prepare("SELECT donor_id FROM request_matches WHERE request_id=? AND match_status='accepted' LIMIT 1");$m->bind_param('i',$id);$m->execute();$match=$m->get_result()->fetch_assoc();if($match){$cert='BN-'.date('Y').'-'.str_pad($id,5,'0',STR_PAD_LEFT);$did=(int)$match['donor_id'];$hid=(int)$r['hospital_id'];$units=(int)$r['units'];$code='QR-'.$id.'-'.substr(bin2hex(random_bytes(4)),0,6);$ins=$conn->prepare('INSERT INTO donation_records(request_id,donor_id,hospital_id,units,verification_code,certificate_no) VALUES(?,?,?,?,?,?)');$ins->bind_param('iiiiss',$id,$did,$hid,$units,$code,$cert);$ins->execute();$dp=$conn->prepare("UPDATE donor_profiles SET total_donations=total_donations+1,last_donation_date=CURDATE(),availability='recently_donated' WHERE user_id=?");$dp->bind_param('i',$did);$dp->execute();$rm=$conn->prepare("UPDATE request_matches SET match_status='completed' WHERE request_id=? AND donor_id=?");$rm->bind_param('ii',$id,$did);$rm->execute();case_event($conn,$id,'Donation verified','Certificate '.$cert.' generated');}}flash('success','Case advanced to '.status_label($next).'.');}}
 header('Location: request-view.php?id='.$id);exit;}
$st=$conn->prepare("SELECT br.*,h.name hospital_name,h.phone hospital_phone,u.name requester_name FROM blood_requests br LEFT JOIN hospitals h ON h.id=br.hospital_id JOIN users u ON u.id=br.requester_id WHERE br.id=?");$st->bind_param('i',$id);$st->execute();$r=$st->get_result()->fetch_assoc();if(!$r){http_response_code(404);die('Request not found');}
$m=$conn->prepare("SELECT rm.*,u.name,dp.blood_group,dp.city,dp.total_donations,dp.availability FROM request_matches rm JOIN users u ON u.id=rm.donor_id JOIN donor_profiles dp ON dp.user_id=u.id WHERE rm.request_id=? ORDER BY rm.readiness_score DESC,rm.distance_km ASC");$m->bind_param('i',$id);$m->execute();$matches=$m->get_result();
$h=$conn->prepare("SELECT ch.*,u.name FROM case_history ch LEFT JOIN users u ON u.id=ch.user_id WHERE ch.request_id=? ORDER BY ch.created_at DESC");$h->bind_param('i',$id);$h->execute();$history=$h->get_result();$don=$conn->prepare('SELECT dr.*,u.name donor_name,h.name hospital_name FROM donation_records dr JOIN users u ON u.id=dr.donor_id LEFT JOIN hospitals h ON h.id=dr.hospital_id WHERE dr.request_id=? LIMIT 1');$don->bind_param('i',$id);$don->execute();$record=$don->get_result()->fetch_assoc();
$pageTitle='Live Case #'.$id;include 'includes/header.php';$steps=['submitted','verified','matching','accepted','arrived','collected','completed'];$idx=array_search($r['status'],$steps);?>
<section class="page-hero"><div class="container"><span class="kicker">Case BN-<?=str_pad($id,5,'0',STR_PAD_LEFT)?></span><h1>Live emergency case</h1><p>Track donor matching, operational progress and the permanent case history from one screen.</p></div></section><section class="section-sm"><div class="container request-detail"><div><div class="case-banner"><span class="priority <?=e($r['priority'])?>"><?=priority_icon($r['priority'])?> <?=e($r['priority'])?></span><h2><?=e($r['patient_name'])?> needs <?=e($r['blood_group'])?></h2><p><?=e($r['hospital_name']?:$r['address'])?> • <?=e($r['reason'])?></p><div class="case-stats"><div><span>Units</span><b><?=$r['units']?></b></div><div><span>Radius</span><b><?=$r['broadcast_radius']?> km</b></div><div><span>Needed by</span><b><?=date('M d, h:i A',strtotime($r['needed_by']))?></b></div><div><span>Status</span><b><?=e(status_label($r['status']))?></b></div></div></div>
<div class="panel"><h3>Matched donors</h3><?php if($matches->num_rows):while($mm=$matches->fetch_assoc()):?><div class="match-card"><div class="score"><?=$mm['readiness_score']?>%</div><div><b><?=e($mm['name'])?> • <?=e($mm['blood_group'])?></b><span><?=e($mm['city'])?> • <?=$mm['distance_km']?> km • <?=$mm['total_donations']?> donations</span></div><div><span class="badge <?=$mm['match_status']==='accepted'||$mm['match_status']==='completed'?'green':'red'?>"><?=e($mm['match_status'])?></span><?php if(is_role('donor')&&user()['id']==$mm['donor_id']&&in_array($mm['match_status'],['notified','suggested'],true)):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="accept"><button class="btn btn-sm btn-primary" style="margin-top:7px">Accept</button></form><?php endif;?></div></div><?php endwhile;else:?><div class="empty">No donor is inside the current radius yet.</div><?php endif;?></div>
<div class="panel" style="margin-top:18px"><h3>Permanent case history</h3><div class="timeline"><?php while($ev=$history->fetch_assoc()):?><div class="time-item done"><b><?=e($ev['event_name'])?></b><span><?=e($ev['note'])?> • <?=e($ev['name']?:'System')?> • <?=date('M d, Y h:i A',strtotime($ev['created_at']))?></span></div><?php endwhile;?></div></div>
<?php if($record):?><div class="panel certificate-card" style="margin-top:18px"><span class="kicker">Verified donation record</span><h3><?=e($record['certificate_no'])?></h3><p class="form-note"><?=e($record['donor_name'])?> donated <?=$record['units']?> unit(s) at <?=e($record['hospital_name'])?> on <?=date('M d, Y',strtotime($record['donated_at']))?>.</p><span class="badge green"><i class="fa-solid fa-circle-check"></i> Verification: <?=e($record['verification_code'])?></span></div><?php endif;?></div>
<aside><div class="panel"><h3>Rescue timeline</h3><div class="timeline"><?php foreach($steps as $i=>$s):?><div class="time-item <?=$i<$idx?'done':($i===$idx?'active':'')?>"><b><?=e(status_label($s))?></b><span><?=$i<=$idx?'Reached':'Pending'?></span></div><?php endforeach;?></div><?php if(is_role('admin','hospital')&&$r['status']!=='completed'):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="next"><button class="btn btn-primary" style="width:100%">Advance case status</button></form><?php endif;?></div><div class="panel" style="margin-top:18px"><h3>Emergency broadcast</h3><p class="form-note">Expand beyond <?=$r['broadcast_radius']?> km when more compatible donors are needed.</p><?php if(logged_in()&&is_role('admin','hospital','requester')&&$r['status']!=='completed'):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="expand"><button class="btn btn-dark" style="width:100%"><i class="fa-solid fa-tower-broadcast"></i> Expand radius +5 km</button></form><?php endif;?></div></aside></div></section><?php include 'includes/footer.php';?>
